package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();rows,e:=p.Query(c,`with latest as(select distinct on(h.recording_id) h.recording_id,h.window_end_at,case when h.metric_version=2 and h.overlap_count=0 and h.coverage_pct>=95 and h.largest_gap_seconds<=900 and h.gap_over_5m_count<=1 and h.gap_over_30s_count<=6 then 'GOOD' when h.clip_count=0 or h.coverage_pct=0 then 'F' when h.coverage_pct<80 then 'E' else 'D' end grade from recording_window_health h order by h.recording_id,h.window_end_at desc) select r.id,r.status,r.end_at,l.window_end_at,l.grade,(select count(*) from recording_jobs j where j.recording_id=r.id and j.status='pending'),(select count(*) from recording_jobs j where j.recording_id=r.id and j.status='leased' and j.lease_expires_at>now()),(select count(*) from recording_jobs j where j.recording_id=r.id and j.handoff_until>now()),(select count(*) from recording_upload_intents u where u.recording_id=r.id and u.status='pending' and u.expires_at>now()) from recordings r left join latest l on l.recording_id=r.id where r.account_id=47 and r.status='active' order by r.id`);if e!=nil{panic(e)};defer rows.Close();for rows.Next(){var id,pnd,lease,hand,intents int;var st,grade string;var end,win any;if e:=rows.Scan(&id,&st,&end,&win,&grade,&pnd,&lease,&hand,&intents);e!=nil{panic(e)};fmt.Printf("%d status=%s end=%v latest=%v grade=%s gates=p%d/l%d/h%d/i%d\n",id,st,end,win,grade,pnd,lease,hand,intents)}}
